{"items":[{"id":"cap-v2-replacement-associative_aggregation-rust-repair-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::{aggregate_measurements, Measurement};
use std::collections::HashMap;

fn measurement(local_name: &str, value: i64) -> Measurement {
    Measurement {
        local_name: local_name.to_string(),
        value,
    }
}

#[test]
fn aggregates_aliased_and_unaliased_measurements() {
    let measurements = vec![
        measurement("indoor", 10),
        measurement("room_sensor", -3),
        measurement("outdoor", 7),
        measurement("indoor", 5),
    ];
    let aliases = HashMap::from([
        ("indoor".to_string(), "temperature".to_string()),
        ("room_sensor".to_string(), "temperature".to_string()),
    ]);

    let totals = aggregate_measurements(&measurements, &aliases);

    assert_eq!(totals.len(), 2);
    let temperature = totals.get("temperature").expect("aliased group missing");
    assert_eq!(temperature.count, 3);
    assert_eq!(temperature.sum, 12);
    let outdoor = totals.get("outdoor").expect("local group missing");
    assert_eq!(outdoor.count, 1);
    assert_eq!(outdoor.sum, 7);
    assert!(!totals.contains_key("indoor"));
    assert!(!totals.contains_key("room_sensor"));
}

#[test]
fn empty_measurements_produce_an_empty_map() {
    let measurements: Vec<Measurement> = Vec::new();
    let aliases = HashMap::from([("unused".to_string(), "canonical".to_string())]);

    let totals = aggregate_measurements(&measurements, &aliases);

    assert!(totals.is_empty());
}

#[test]
fn empty_alias_map_groups_by_local_name() {
    let measurements = vec![measurement("sensor-a", 4), measurement("sensor-a", 6)];
    let aliases = HashMap::new();

    let totals = aggregate_measurements(&measurements, &aliases);

    assert_eq!(totals.len(), 1);
    let total = totals.get("sensor-a").expect("local group missing");
    assert_eq!(total.count, 2);
    assert_eq!(total.sum, 10);
}

#[test]
fn alias_resolution_is_exact_and_one_step_only() {
    let measurements = vec![
        measurement("a", 2),
        measurement("b", 3),
        measurement("A", 5),
        measurement("missing", 7),
    ];
    let aliases = HashMap::from([
        ("a".to_string(), "b".to_string()),
        ("b".to_string(), "c".to_string()),
        ("unused".to_string(), "ignored".to_string()),
    ]);

    let totals = aggregate_measurements(&measurements, &aliases);

    assert_eq!(totals.len(), 4);
    let b = totals.get("b").expect("one-step alias target missing");
    assert_eq!(b.count, 1);
    assert_eq!(b.sum, 2);
    let c = totals.get("c").expect("direct alias target missing");
    assert_eq!(c.count, 1);
    assert_eq!(c.sum, 3);
    let uppercase = totals.get("A").expect("alias matching must be exact");
    assert_eq!(uppercase.count, 1);
    assert_eq!(uppercase.sum, 5);
    let missing = totals.get("missing").expect("unmapped local name missing");
    assert_eq!(missing.count, 1);
    assert_eq!(missing.sum, 7);
}

#[test]
fn supports_empty_names_and_empty_canonical_names() {
    let measurements = vec![
        measurement("", 8),
        measurement("blank_alias", -2),
        measurement("plain", 1),
    ];
    let aliases = HashMap::from([("blank_alias".to_string(), "".to_string())]);

    let totals = aggregate_measurements(&measurements, &aliases);

    assert_eq!(totals.len(), 2);
    let empty = totals.get("").expect("empty-name group missing");
    assert_eq!(empty.count, 2);
    assert_eq!(empty.sum, 6);
    let plain = totals.get("plain").expect("plain group missing");
    assert_eq!(plain.count, 1);
    assert_eq!(plain.sum, 1);
}

#[test]
fn handles_i64_boundaries_without_exceeding_them() {
    let measurements = vec![
        measurement("maximum", i64::MAX),
        measurement("maximum_zero", 0),
        measurement("minimum", i64::MIN),
        measurement("minimum_zero", 0),
    ];
    let aliases = HashMap::from([
        ("maximum_zero".to_string(), "maximum".to_string()),
        ("minimum_zero".to_string(), "minimum".to_string()),
    ]);

    let totals = aggregate_measurements(&measurements, &aliases);

    let maximum = totals.get("maximum").expect("maximum group missing");
    assert_eq!(maximum.count, 2);
    assert_eq!(maximum.sum, i64::MAX);
    let minimum = totals.get("minimum").expect("minimum group missing");
    assert_eq!(minimum.count, 2);
    assert_eq!(minimum.sum, i64::MIN);
}

#[test]
fn repeated_calls_are_stable() {
    let measurements = vec![
        measurement("left", 11),
        measurement("right", -4),
        measurement("other", 9),
    ];
    let aliases = HashMap::from([
        ("left".to_string(), "combined".to_string()),
        ("right".to_string(), "combined".to_string()),
    ]);

    let first = aggregate_measurements(&measurements, &aliases);
    let second = aggregate_measurements(&measurements, &aliases);

    assert_eq!(first.len(), second.len());
    for name in ["combined", "other"] {
        let a = first.get(name).expect("first result missing group");
        let b = second.get(name).expect("second result missing group");
        assert_eq!(a.count, b.count);
        assert_eq!(a.sum, b.sum);
    }
}

#[test]
fn inputs_are_not_modified() {
    let measurements = vec![
        measurement("local-one", 13),
        measurement("local-two", -6),
    ];
    let aliases = HashMap::from([
        ("local-one".to_string(), "shared".to_string()),
        ("unused".to_string(), "elsewhere".to_string()),
    ]);
    let measurement_snapshot: Vec<(String, i64)> = measurements
        .iter()
        .map(|m| (m.local_name.clone(), m.value))
        .collect();
    let alias_snapshot = aliases.clone();

    {
        let totals = aggregate_measurements(&measurements, &aliases);
        let shared = totals.get("shared").expect("aliased group missing");
        assert_eq!(shared.count, 1);
        assert_eq!(shared.sum, 13);
    }

    assert_eq!(measurements.len(), measurement_snapshot.len());
    for (actual, (expected_name, expected_value)) in
        measurements.iter().zip(measurement_snapshot.iter())
    {
        assert_eq!(&actual.local_name, expected_name);
        assert_eq!(actual.value, *expected_value);
    }
    assert_eq!(aliases, alias_snapshot);
}

#[test]
fn returned_keys_borrow_existing_input_names() {
    let measurements = vec![measurement("aliased", 1), measurement("local", 2)];
    let aliases = HashMap::from([("aliased".to_string(), "canonical".to_string())]);

    let totals = aggregate_measurements(&measurements, &aliases);
    let canonical_key = totals
        .keys()
        .copied()
        .find(|name| *name == "canonical")
        .expect("canonical key missing");
    let local_key = totals
        .keys()
        .copied()
        .find(|name| *name == "local")
        .expect("local key missing");

    let stored_canonical = aliases.get("aliased").expect("alias missing").as_str();
    let stored_local = measurements[1].local_name.as_str();
    assert!(std::ptr::eq(canonical_key.as_ptr(), stored_canonical.as_ptr()));
    assert!(std::ptr::eq(local_key.as_ptr(), stored_local.as_ptr()));
}"}]}

