{"items":[{"id":"cap-v2-replacement-numeric_reasoning-rust-repair-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::RatioAccumulator;

#[test]
fn channels_start_empty_and_zero_input_is_stable() {
    let mut accumulator = RatioAccumulator::new(3, 2, 3, 10);

    for channel in 0..3 {
        assert_eq!(accumulator.total(channel), 0);
        assert_eq!(accumulator.remainder(channel), 0);
    }

    assert_eq!(accumulator.record(1, 0), 0);
    assert_eq!(accumulator.total(1), 0);
    assert_eq!(accumulator.remainder(1), 0);
}

#[test]
fn accumulates_fractional_remainder_across_records() {
    let mut accumulator = RatioAccumulator::new(1, 2, 3, 10);

    assert_eq!(accumulator.record(0, 1), 0);
    assert_eq!(accumulator.total(0), 0);
    assert_eq!(accumulator.remainder(0), 2);

    assert_eq!(accumulator.record(0, 1), 1);
    assert_eq!(accumulator.total(0), 1);
    assert_eq!(accumulator.remainder(0), 1);

    assert_eq!(accumulator.record(0, 1), 1);
    assert_eq!(accumulator.total(0), 2);
    assert_eq!(accumulator.remainder(0), 0);
}

#[test]
fn channels_have_independent_totals_and_remainders() {
    let mut accumulator = RatioAccumulator::new(2, 2, 3, 20);

    assert_eq!(accumulator.record(0, 1), 0);
    assert_eq!(accumulator.total(0), 0);
    assert_eq!(accumulator.remainder(0), 2);
    assert_eq!(accumulator.total(1), 0);
    assert_eq!(accumulator.remainder(1), 0);

    assert_eq!(accumulator.record(1, 1), 0);
    assert_eq!(accumulator.remainder(0), 2);
    assert_eq!(accumulator.remainder(1), 2);

    assert_eq!(accumulator.record(0, 1), 1);
    assert_eq!(accumulator.total(0), 1);
    assert_eq!(accumulator.remainder(0), 1);
    assert_eq!(accumulator.total(1), 0);
    assert_eq!(accumulator.remainder(1), 2);
}

#[test]
fn saturation_discards_whole_credits_but_keeps_new_remainder() {
    let mut accumulator = RatioAccumulator::new(1, 5, 3, 1);

    assert_eq!(accumulator.record(0, 1), 1);
    assert_eq!(accumulator.total(0), 1);
    assert_eq!(accumulator.remainder(0), 2);

    assert_eq!(accumulator.record(0, 1), 0);
    assert_eq!(accumulator.total(0), 1);
    assert_eq!(accumulator.remainder(0), 1);

    assert_eq!(accumulator.record(0, 0), 0);
    assert_eq!(accumulator.total(0), 1);
    assert_eq!(accumulator.remainder(0), 1);
}

#[test]
fn zero_limit_still_tracks_fractional_remainder() {
    let mut accumulator = RatioAccumulator::new(1, 2, 3, 0);

    assert_eq!(accumulator.record(0, 1), 0);
    assert_eq!(accumulator.total(0), 0);
    assert_eq!(accumulator.remainder(0), 2);
}

#[test]
fn maximum_inputs_do_not_overflow_or_wrap_total() {
    let maximum = u64::MAX;
    let mut accumulator = RatioAccumulator::new(1, maximum, 1, maximum);

    assert_eq!(accumulator.record(0, maximum), maximum);
    assert_eq!(accumulator.total(0), maximum);
    assert_eq!(accumulator.remainder(0), 0);

    assert_eq!(accumulator.record(0, maximum), 0);
    assert_eq!(accumulator.total(0), maximum);
    assert_eq!(accumulator.remainder(0), 0);
}

#[test]
fn near_maximum_weighted_sum_is_computed_exactly() {
    let maximum = u64::MAX;
    let mut accumulator = RatioAccumulator::new(1, maximum - 1, maximum, maximum);

    assert_eq!(accumulator.record(0, 1), 0);
    assert_eq!(accumulator.remainder(0), maximum - 1);

    assert_eq!(accumulator.record(0, maximum), maximum - 1);
    assert_eq!(accumulator.total(0), maximum - 1);
    assert_eq!(accumulator.remainder(0), maximum - 1);
}

#[test]
fn zero_channels_can_be_constructed() {
    let _accumulator = RatioAccumulator::new(0, 1, 1, 1);
}

#[test]
#[should_panic]
fn zero_denominator_panics() {
    let _accumulator = RatioAccumulator::new(1, 1, 0, 1);
}

#[test]
#[should_panic]
fn record_with_invalid_channel_panics() {
    let mut accumulator = RatioAccumulator::new(1, 1, 1, 1);
    accumulator.record(1, 0);
}

#[test]
#[should_panic]
fn total_with_invalid_channel_panics() {
    let accumulator = RatioAccumulator::new(1, 1, 1, 1);
    accumulator.total(1);
}

#[test]
#[should_panic]
fn remainder_with_invalid_channel_panics() {
    let accumulator = RatioAccumulator::new(1, 1, 1, 1);
    accumulator.remainder(1);
}
"}]}

