pub struct RatioAccumulator {
    numerator: u64,
    denominator: u64,
    limit: u64,
    totals: Vec<u64>,
    remainder: u64,
}

impl RatioAccumulator {
    pub fn new(channels: usize, numerator: u64, denominator: u64, limit: u64) -> Self {
        assert!(denominator != 0, "denominator must be nonzero");
        Self {
            numerator,
            denominator,
            limit,
            totals: vec![0; channels],
            remainder: 0,
        }
    }

    pub fn record(&mut self, channel: usize, input: u64) -> u64 {
        let weighted = input as u128 * self.numerator as u128 + self.remainder as u128;
        let produced = weighted / self.denominator as u128;
        self.remainder = (weighted % self.denominator as u128) as u64;

        let available = self.limit - self.totals[channel];
        let credited = produced.min(available as u128) as u64;
        self.totals[channel] += credited;
        credited
    }

    pub fn total(&self, channel: usize) -> u64 {
        self.totals[channel]
    }

    pub fn remainder(&self, _channel: usize) -> u64 {
        self.remainder
    }
}
